package vn.iotstar.service.impl; import com.cloudinary.Cloudinary; import com.cloudinary.utils.ObjectUtils; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import vn.iotstar.service.*; @Service @RequiredArgsConstructor public class CloudinaryServiceImpl implements CloudinaryService{private final Cloudinary cloudinary; public CloudinaryUploadResult upload(MultipartFile f){try{var r=cloudinary.uploader().upload(f.getBytes(),ObjectUtils.asMap("folder","iotstar-products"));return new CloudinaryUploadResult((String)r.get("secure_url"),(String)r.get("public_id"));}catch(Exception e){throw new IllegalArgumentException("Upload ảnh thất bại: "+e.getMessage(),e);}} public void delete(String id){try{cloudinary.uploader().destroy(id,ObjectUtils.emptyMap());}catch(Exception ignored){}}}